-- ==========================================================================
-- PART 4: 20261019000002_revoke_availability_rpcs
-- ==========================================================================
begin;
-- Take reserve_availability() and release_availability() off the public API.
--
-- Both are `security definer`, so they write availability_slots with RLS bypassed, and both were
-- executable by PUBLIC — the default for a new function. PUBLIC includes `anon`, so anyone holding
-- the anon key, which ships in the browser bundle by design, could call them without an account.
--
-- Verified before this migration: as `anon` with no JWT, reserve_availability(slot, 12) moved a
-- 12-seat slot from 0 booked to 12 booked with no bookings behind it. Repeated across slots that
-- empties the marketplace, and release_availability() is the mirror — lower booked_count while
-- bookings still exist and the vendor oversells the boat.
--
-- Neither function needs to be reachable from a browser. The only callers are in
-- supabase/functions/_shared/supabaseStore.ts, which runs on the service role, so the grant is
-- narrowed to that role rather than the functions being rewritten to check the caller.
--
-- REVOKE FROM PUBLIC, not from anon and authenticated. A grant held by PUBLIC applies to every
-- role, so revoking the two named roles leaves the privilege in place and changes nothing. The
-- test asserts the denial rather than trusting this comment.

revoke execute on function reserve_availability(uuid, integer) from public;
revoke execute on function release_availability(uuid, integer) from public;

-- Belt and braces: Supabase projects sometimes carry explicit role grants from earlier tooling,
-- and revoking a privilege that was never granted is not an error.
revoke execute on function reserve_availability(uuid, integer) from anon, authenticated;
revoke execute on function release_availability(uuid, integer) from anon, authenticated;

grant execute on function reserve_availability(uuid, integer) to service_role;
grant execute on function release_availability(uuid, integer) to service_role;
commit;

-- ==========================================================================
-- PART 5: 20261020000001_vendor_onboarding
-- ==========================================================================
begin;
-- Vendor onboarding writes a real organisation.
--
-- apps/vendor-web/app/onboarding/page.tsx collected six fields, slept 800ms and routed to
-- /billing. Nothing was stored, so a live deployment would hold zero vendor_organizations rows —
-- and every public RLS policy gates on status = 'approved', so it would also show zero listings.
--
-- ## Why this has to be a function and not two client inserts
--
-- The obvious shape is two PostgREST calls: insert the organisation under vendor_orgs_insert
-- (`with check (auth.uid() is not null)`), then insert the owner membership. The second call
-- CANNOT SUCCEED. The only insert-side policy on vendor_members is vendor_members_owner_manage,
-- whose check is `is_vendor_owner(vendor_org_id) or is_admin()`, and is_vendor_owner() reads
-- vendor_members for an existing 'vendor_owner' row. Before the first member row exists there is
-- no owner, so the policy refuses the very row that would create one.
--
-- So this is not the usual "two writes might half-fail" argument. The client path does not race;
-- it always lands an ownerless organisation, which is then unreachable forever:
-- vendor_orgs_owner_update needs is_vendor_owner() too, and vendor_orgs_member_read needs
-- is_vendor_member(), so the applicant cannot even see the row they just created. One
-- `security definer` function doing both under one transaction is the only shape that works.
--
-- ## The grant
--
-- `security definer` bypasses RLS, so EXECUTE is the only thing standing between a caller and
-- these tables — see 20261019000002, where two such functions sat on the default PUBLIC grant and
-- let anyone holding the browser's anon key rewrite availability. REVOKE FROM PUBLIC first
-- (revoking from anon/authenticated alone is a no-op while PUBLIC holds the grant), then grant to
-- `authenticated` only.
--
-- The owner is read from auth.uid() rather than taken as a parameter. A p_user_id argument on a
-- definer function is an impersonation primitive: any signed-in caller could make someone else the
-- owner of an organisation, or themselves the owner of a hand-picked id.

-- --------------------------------------------------------------------------
-- The two columns the form had nowhere to put
-- --------------------------------------------------------------------------
--
-- vendor_organizations had contact_email and contact_phone but no contact_name, while the form
-- asks for "Primary contact". business_type had no column at all. Both were discarded on submit;
-- adding them is what makes the write lossless.
--
-- Bounded in all three live layers (see the decision record of 2026-10-19): VENDOR_LIMITS and the
-- schemas in packages/types/src/vendor.ts, the checks here, and maxLength on the inputs.
-- `char_length(null)` is null and a CHECK passes on null, which is what lets these sit on
-- nullable columns; btrim for the non-blank tests, because Zod trims before it measures.

alter table vendor_organizations
  add column contact_name  text,
  add column business_type text;

alter table vendor_organizations
  add constraint vendor_organizations_legal_name_length
    check (char_length(legal_name) <= 120),
  add constraint vendor_organizations_legal_name_not_blank
    check (char_length(btrim(legal_name)) > 0),
  add constraint vendor_organizations_trading_name_length
    check (char_length(trading_name) <= 120),
  add constraint vendor_organizations_trading_name_not_blank
    check (char_length(btrim(trading_name)) > 0),
  add constraint vendor_organizations_contact_name_length
    check (char_length(contact_name) <= 120),
  add constraint vendor_organizations_contact_phone_length
    check (char_length(contact_phone) <= 40),
  -- Mirrors VENDOR_BUSINESS_TYPES. A text column with a check rather than an enum: the taxonomy is
  -- marketing copy that will be re-cut, and a check constraint is one ALTER to change where an
  -- enum value can never be removed.
  add constraint vendor_organizations_business_type
    check (business_type is null or business_type in (
      'tour', 'food', 'wellness', 'water', 'culture', 'transport', 'retail', 'other'
    ));

-- --------------------------------------------------------------------------
-- create_vendor_organization
-- --------------------------------------------------------------------------

create or replace function create_vendor_organization(
  p_island_id     uuid,
  p_legal_name    text,
  p_trading_name  text,
  p_contact_name  text,
  p_contact_phone text,
  p_business_type text,
  p_description   text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user  uuid := auth.uid();
  v_email text;
  v_org   uuid;
begin
  if v_user is null then
    raise exception 'Sign in before applying.' using errcode = '42501';
  end if;

  -- An applicant gets one organisation. Without this, a double-submitted form — or a refresh on
  -- /onboarding — leaves two pending applications for one business, and an admin reviewing the
  -- queue has no way to tell which is the real one.
  if exists (select 1 from vendor_members where user_id = v_user) then
    raise exception 'This account already belongs to a vendor organisation.'
      using errcode = '23505';
  end if;

  -- contact_email is not null on the table and is the only address the approval mail can go to, so
  -- it comes from the authenticated identity rather than the form: a self-declared contact address
  -- on a definer function is a way to receive another business's review correspondence. An
  -- anonymous session has no email, which is also why the vendor portal signs in by magic link.
  select email into v_email from auth.users where id = v_user;
  if v_email is null or btrim(v_email) = '' then
    raise exception 'This account has no email address; apply from an email sign-in.'
      using errcode = '42501';
  end if;

  -- The island is a not-null FK, and an application filed under a market that has not launched
  -- would sit in the queue forever. islands_public_read only exposes active islands anyway, so
  -- this is the server-side half of a choice the client could not legitimately make.
  if not exists (select 1 from islands where id = p_island_id and is_active) then
    raise exception 'That island is not open for applications.' using errcode = '23503';
  end if;

  -- 'pending_review', not 'pending' — see the vendor_status enum, whose states are draft,
  -- pending_review, approved, changes_requested, rejected, suspended. The column DEFAULTS to
  -- 'draft', which would leave a completed application looking unsubmitted and absent from any
  -- review queue, so it is set explicitly here.
  insert into vendor_organizations (
    island_id, legal_name, trading_name, contact_email, contact_phone,
    contact_name, business_type, description, status
  )
  values (
    p_island_id, p_legal_name, p_trading_name, v_email, p_contact_phone,
    p_contact_name, p_business_type, p_description, 'pending_review'
  )
  returning id into v_org;

  -- can_manage_listings is false by default and stays false: isListingManager() and the RLS helper
  -- both treat an owner as a manager whatever the flag says, so setting it here would only create a
  -- second source of truth that could disagree. can_view_payouts is the owner's by right.
  insert into vendor_members (vendor_org_id, user_id, role, can_scan_vouchers, can_view_payouts)
  values (v_org, v_user, 'vendor_owner', true, true);

  -- The applicant named a contact; profiles.display_name is where the portal reads a human name
  -- from. Only filled if blank, so this cannot overwrite a name the user chose themselves.
  update profiles
     set display_name = p_contact_name
   where id = v_user
     and p_contact_name is not null
     and coalesce(btrim(display_name), '') = '';

  return v_org;
end;
$$;

revoke execute on function create_vendor_organization(uuid, text, text, text, text, text, text)
  from public;
revoke execute on function create_vendor_organization(uuid, text, text, text, text, text, text)
  from anon;
grant execute on function create_vendor_organization(uuid, text, text, text, text, text, text)
  to authenticated;
commit;

-- ==========================================================================
-- PART 6: 20261020000002_guard_vendor_review_fields
-- ==========================================================================
begin;
-- Only an admin may move a vendor's review state.
--
-- `vendor_orgs_owner_update` grants an owner `for update using (is_vendor_owner(id))`, and RLS has
-- no column-level control, so that policy covered `status` along with the trading name. A vendor
-- owner could therefore approve their own organisation.
--
-- Verified before this migration: as the owner of a `pending_review` organisation, a plain
-- `update vendor_organizations set status = 'approved'` succeeded. Since onboarding makes the
-- applicant a `vendor_owner`, anyone who completed it could make themselves publicly visible
-- without review — and PRD §1 sells the marketplace on verified vendors, with every public policy
-- gating on `status = 'approved'`.
--
-- A trigger rather than a policy, because the privilege is per-column and RLS is per-row. This
-- mirrors `guard_profile_privileges()`, which exists for exactly the same reason: a tourist must
-- not be able to set their own `profiles.role` even though they may update their own profile row.
--
-- Column privileges would not work here either. Admins and vendors are both the `authenticated`
-- database role, so `grant update (…) on vendor_organizations to authenticated` cannot tell them
-- apart. The caller's identity is only visible to a function.

create or replace function guard_vendor_review_fields()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- No end-user context means a service-role caller: an Edge Function, a migration or the seed,
  -- all of which already hold the service key and sit inside the trust boundary. `anon` also has
  -- no uid, but has no UPDATE policy on this table, so RLS refuses it before this runs.
  if auth.uid() is null then
    return new;
  end if;

  if new.status is distinct from old.status
     or new.review_notes is distinct from old.review_notes
     or new.reviewed_by is distinct from old.reviewed_by
     or new.reviewed_at is distinct from old.reviewed_at
  then
    if not is_admin() then
      raise exception 'only a platform administrator may change a vendor''s review state';
    end if;
  end if;

  return new;
end;
$$;

comment on function guard_vendor_review_fields() is
  'Blocks non-admin writes to vendor_organizations.status and its review columns. RLS cannot express a per-column rule.';

create trigger vendor_organizations_review_guard
  before update on vendor_organizations
  for each row execute function guard_vendor_review_fields();

-- `reviewed_by` should name the admin who decided, and the console has no business being trusted
-- to send the right id. Stamp it from the authenticated identity instead.
create or replace function stamp_vendor_review()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.status is distinct from old.status and auth.uid() is not null then
    new.reviewed_by := auth.uid();
    new.reviewed_at := now();
  end if;
  return new;
end;
$$;

-- Postgres fires same-timing triggers in alphabetical order by name, so `…_review_guard` runs
-- before `…_review_stamp`: a refused update raises before this one can stamp anything. The names
-- carry that ordering, so do not rename either without checking the other.
create trigger vendor_organizations_review_stamp
  before update on vendor_organizations
  for each row execute function stamp_vendor_review();
commit;

-- ==========================================================================
-- PART 7: 20261020000003_redeem_voucher_entry_point
-- ==========================================================================
begin;
-- Give the scanner a redemption RPC it can actually call, and stop the old one being callable.
--
-- `apps/vendor-web/lib/redeem.ts` called `redeem_voucher({p_token, p_scanner_name})`. No migration
-- ever defined that signature — the only one was `redeem_voucher(p_token_hash, p_vendor_org_id,
-- p_scanner_user_id, p_device_meta)`. The two-argument contract existed only in the hand-written
-- `packages/supabase/src/database.types.ts`, so `pnpm typecheck` passed and PostgREST returned
-- PGRST202 at runtime: every live scan threw. Demo mode hid it, because `isDemoScanner`
-- short-circuits before the RPC.
--
-- The old function was also executable by PUBLIC and took the scanner's identity and the vendor
-- org as parameters, checking neither against the caller. Verified before this migration: a
-- tourist with no vendor membership redeemed an organisation's voucher (`ok`, voucher burned,
-- `redeemed_by` set to whatever uuid was passed), and a `vendor_staff` with
-- `can_scan_vouchers = false` redeemed one too. `can_scan_for_vendor()` has existed since the
-- first functions migration and was referenced by nothing.
--
-- Shape: the decision logic is untouched and becomes an internal engine; a thin authenticated
-- entry point sits in front of it.

-- --------------------------------------------------------------------------
-- The hash, in one place
-- --------------------------------------------------------------------------
--
-- Must equal `hashVoucherToken()` in packages/types/src/voucher.ts: **base64url** of the sha256,
-- unpadded, of the trimmed token. Two ways to get this wrong, both of which make a valid voucher
-- report `unknown_token` — indistinguishable from a forged QR at the gate:
--
--   1. `encode(…, 'base64')` is standard base64. Its `+`, `/` and `=` are `-`, `_` and nothing in
--      base64url. pgcrypto also wraps long base64 output; a 32-byte digest never reaches the wrap
--      width, but stripping newlines costs nothing and removes the question.
--   2. `btrim(x)` strips SPACES ONLY, while JavaScript `.trim()` also strips newlines, tabs and
--      carriage returns. A scanner that appends a newline would hash to something else entirely.
--      Hence the regexp, which matches `\s` as `.trim()` does.
--
-- `sha256(bytea)` is built in (PG 11+). `digest()` is not usable here: Supabase installs pgcrypto
-- in the `extensions` schema, outside this function's `search_path`, so it fails with "function
-- digest(bytea, unknown) does not exist" on a real project while passing on the plain-Postgres
-- test harness.
--
-- It lives in its own function so the entry point and `supabase/tests/voucher_hash.test.sql`
-- exercise the same expression rather than two copies that can drift.

create or replace function voucher_token_hash(p_token text)
returns text
language sql
immutable
set search_path = public
as $$
  select rtrim(
    translate(
      replace(
        encode(
          sha256(convert_to(regexp_replace(p_token, '^\s+|\s+$', '', 'g'), 'UTF8')),
          'base64'
        ),
        E'\n', ''
      ),
      '+/', '-_'
    ),
    '='
  );
$$;

comment on function voucher_token_hash(text) is
  'base64url sha256 of the trimmed voucher token. Mirrors hashVoucherToken() in @cvip/types.';

-- --------------------------------------------------------------------------
-- The engine
-- --------------------------------------------------------------------------
--
-- Renamed rather than rewritten, so the row lock, the branch ordering and every outcome stay
-- byte-identical — `atomicity.test.sql` covers all ten branches through this function and keeps
-- doing so. It still trusts its arguments, which is now acceptable because only the service role
-- can call it: Edge Functions and the test suite.

alter function redeem_voucher(text, uuid, uuid, jsonb) rename to redeem_voucher_by_hash;

revoke execute on function redeem_voucher_by_hash(text, uuid, uuid, jsonb) from public;
revoke execute on function redeem_voucher_by_hash(text, uuid, uuid, jsonb) from anon, authenticated;
grant execute on function redeem_voucher_by_hash(text, uuid, uuid, jsonb) to service_role;

comment on function redeem_voucher_by_hash(text, uuid, uuid, jsonb) is
  'Redemption decision engine. Trusts its arguments, so it is service-role only; authenticated callers use redeem_voucher(text, uuid).';

-- --------------------------------------------------------------------------
-- The entry point the scanner calls
-- --------------------------------------------------------------------------
--
-- Takes the raw token from the QR code and the organisation the scanner believes it is scanning
-- for. It derives the scanner from `auth.uid()` and refuses unless that user holds
-- `can_scan_vouchers` for the named organisation, so neither the identity nor the permission is
-- the client's to assert.
--
-- Hashing is `voucher_token_hash()` above, which is pinned against the TypeScript codec by
-- `supabase/tests/voucher_hash.test.sql` and `packages/types/src/voucher.test.ts`.
--
-- The HMAC signature is NOT verified here: the signing secret is deliberately server-side only and
-- has no business in the database. A tampered or fabricated QR therefore fails by hash miss and
-- reports `unknown_token`, which is the same answer a scanner needs, and the attempt is still
-- recorded in `voucher_redemptions`.

create or replace function redeem_voucher(
  p_token         text,
  p_vendor_org_id uuid
)
returns table (
  result               redemption_result,
  voucher_id           uuid,
  redeemed_at          timestamptz,
  original_redeemed_at timestamptz,
  original_scanner     text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_scanner uuid := auth.uid();
  v_hash    text;
  r         record;
begin
  if v_scanner is null then
    raise exception 'redeem_voucher requires a signed-in scanner';
  end if;

  if not can_scan_for_vendor(p_vendor_org_id) then
    -- Not a redemption outcome. A scanner without the permission is a configuration problem for
    -- the vendor to fix, not something to render as a decision about the guest's voucher.
    raise exception 'you do not have permission to scan vouchers for this organisation';
  end if;

  v_hash := voucher_token_hash(p_token);

  select * into r
    from redeem_voucher_by_hash(v_hash, p_vendor_org_id, v_scanner, '{}'::jsonb);

  return query
    select r.result,
           r.voucher_id,
           r.redeemed_at,
           r.original_redeemed_at,
           (select p.display_name from profiles p where p.id = r.original_scanner_id);
end;
$$;

revoke execute on function redeem_voucher(text, uuid) from public;
grant execute on function redeem_voucher(text, uuid) to authenticated;

comment on function redeem_voucher(text, uuid) is
  'Scanner entry point. Hashes the token, derives the scanner from auth.uid() and requires can_scan_vouchers for the named organisation.';
commit;

-- ==========================================================================
-- PART 8: 20261021000001_my_bookings
-- ==========================================================================
begin;
-- my_bookings(): the signed-in tourist's paid bookings, for recovery on a new device.
--
-- A tourist who adds an email and signs in on another phone has an empty local store. Their
-- bookings are on the server, and the owner can already read the `bookings` rows themselves
-- (`bookings_self_read`). What they cannot reliably read is what the booking points at:
--
--   - `availability_slots_public_read` requires `status = 'open'`, so a departure the vendor
--     cancelled after the guest paid loses its `starts_at`.
--   - `experiences_public_read` requires an approved listing under an approved vendor, so a
--     vendor suspended after the guest paid loses the listing title AND (through the same join
--     in the slot policy) the departure time.
--
-- Those are precisely the bookings a guest most needs to see — to know what was cancelled and
-- what they are owed. Widening the public policies to "or you hold a booking against it" would put
-- a bookings subquery on every catalogue read, so this is a narrow `security definer` read instead.
--
-- Because it is security definer, RLS does not protect what it returns. The `user_id = auth.uid()`
-- predicate below IS the access control: with no uid it compares against null and matches nothing,
-- so an anonymous or service-role call returns zero rows rather than every row.
-- supabase/tests/my_bookings.test.sql asserts each of these.
--
-- `pending_payment` and `expired` are excluded: an unpaid checkout is not a booking the guest has,
-- and showing it would put a ticket-less card in Trips.
--
-- Times are returned as `timestamptz`. The tourist app treats slot times as UTC wall-clock (see
-- supabase/functions/resolve-slot/index.ts), and converts back on its side.

create or replace function my_bookings()
returns table (
  id                uuid,
  reference         text,
  status            booking_status,
  seats             integer,
  currency          currency_code,
  subtotal_minor    bigint,
  tax_minor         bigint,
  service_fee_minor bigint,
  total_minor       bigint,
  created_at        timestamptz,
  ticket_token      text,
  experience_title  text,
  island_code       text,
  starts_at         timestamptz,
  guests            jsonb
)
language sql
stable
security definer
set search_path = public
as $$
  select
    b.id,
    b.reference,
    b.status,
    b.seats,
    b.currency,
    b.subtotal_minor,
    b.tax_minor,
    b.service_fee_minor,
    b.total_minor,
    b.created_at,
    b.ticket_token,
    e.title,
    i.code,
    s.starts_at,
    coalesce(
      (
        select jsonb_agg(
                 jsonb_build_object(
                   'kind',              o.kind,
                   'label',             o.label,
                   'quantity',          g.quantity,
                   'unit_amount_minor', g.unit_amount_minor
                 )
                 order by o.sort_order, g.created_at, g.id
               )
          from booking_guests g
          join experience_options o on o.id = g.experience_option_id
         where g.booking_id = b.id
      ),
      '[]'::jsonb
    )
  from bookings b
  join experiences e        on e.id = b.experience_id
  join islands i            on i.id = e.island_id
  join availability_slots s on s.id = b.availability_slot_id
  where b.user_id = auth.uid()
    and b.status in ('confirmed', 'completed', 'cancelled', 'refunded')
  order by s.starts_at desc, b.created_at desc;
$$;

-- REVOKE FROM PUBLIC, not only from anon: a PUBLIC grant applies to every role, so revoking the
-- named role alone changes nothing. The explicit anon revoke covers Supabase projects whose default
-- privileges grant EXECUTE on new functions to anon directly.
revoke execute on function my_bookings() from public;
revoke execute on function my_bookings() from anon;

grant execute on function my_bookings() to authenticated;
-- Edge Functions run as service_role. With no uid they get zero rows, which the test asserts.
grant execute on function my_bookings() to service_role;

comment on function my_bookings() is
  'The caller''s confirmed/completed/cancelled/refunded bookings with slot time, listing title, island code and guests. Security definer so slot/listing RLS cannot hide them; filters on auth.uid().';
commit;

-- ==========================================================================
-- PART 9: 20261021000002_revoke_anon_redeem_voucher
-- ==========================================================================
begin;
-- redeem_voucher(text, uuid) was revoked from PUBLIC only.
--
-- Supabase's default privileges grant EXECUTE on new functions to anon directly, and a PUBLIC
-- revoke does not remove a grant made to a named role. The function still refuses a caller with
-- no uid, so this is hardening and not a live hole, but an unauthenticated caller should not be
-- able to reach it at all. The local harness cannot show the difference (it has no such default
-- grant), so this is verified against a real project, not by supabase/tests.

revoke execute on function redeem_voucher(text, uuid) from anon;
commit;

-- ==========================================================================
-- PART 10: 20261021000003_my_bookings_ticket_token_by_status
-- ==========================================================================
begin;
-- my_bookings(): no scannable ticket for a cancelled or refunded booking.
--
-- 20261021000001 returned `b.ticket_token` for every row it returned, including `cancelled` and
-- `refunded`. A booking row can keep the token it was issued after it is cancelled, so a guest
-- (or anyone holding their phone) could recover a QR for a booking that is no longer valid and
-- present it at the gate. The token is now returned only while the booking is `confirmed` or
-- `completed`; otherwise it is null. Everything else about the function is unchanged: same
-- signature, same rows, same ordering, same grants.
--
-- Hardening: search_path is now `public, pg_temp` (pg_temp last, so a temporary object can never
-- shadow a `public` one inside this security definer function).
--
-- `create or replace` keeps the existing grants; they are restated below anyway so this file
-- alone states the privilege model. supabase/tests/my_bookings.test.sql asserts both the token
-- rule (with confirmed/completed positive controls) and the grants.

create or replace function my_bookings()
returns table (
  id                uuid,
  reference         text,
  status            booking_status,
  seats             integer,
  currency          currency_code,
  subtotal_minor    bigint,
  tax_minor         bigint,
  service_fee_minor bigint,
  total_minor       bigint,
  created_at        timestamptz,
  ticket_token      text,
  experience_title  text,
  island_code       text,
  starts_at         timestamptz,
  guests            jsonb
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select
    b.id,
    b.reference,
    b.status,
    b.seats,
    b.currency,
    b.subtotal_minor,
    b.tax_minor,
    b.service_fee_minor,
    b.total_minor,
    b.created_at,
    case when b.status in ('confirmed', 'completed') then b.ticket_token else null end,
    e.title,
    i.code,
    s.starts_at,
    coalesce(
      (
        select jsonb_agg(
                 jsonb_build_object(
                   'kind',              o.kind,
                   'label',             o.label,
                   'quantity',          g.quantity,
                   'unit_amount_minor', g.unit_amount_minor
                 )
                 order by o.sort_order, g.created_at, g.id
               )
          from booking_guests g
          join experience_options o on o.id = g.experience_option_id
         where g.booking_id = b.id
      ),
      '[]'::jsonb
    )
  from bookings b
  join experiences e        on e.id = b.experience_id
  join islands i            on i.id = e.island_id
  join availability_slots s on s.id = b.availability_slot_id
  where b.user_id = auth.uid()
    and b.status in ('confirmed', 'completed', 'cancelled', 'refunded')
  order by s.starts_at desc, b.created_at desc;
$$;

revoke execute on function my_bookings() from public;
revoke execute on function my_bookings() from anon;

grant execute on function my_bookings() to authenticated;
grant execute on function my_bookings() to service_role;

comment on function my_bookings() is
  'The caller''s confirmed/completed/cancelled/refunded bookings with slot time, listing title, island code and guests. Ticket token only for confirmed/completed, null otherwise. Security definer so slot/listing RLS cannot hide them; filters on auth.uid().';
commit;

-- ==========================================================================
-- PART 11: 20261022000001_transfer_guest_bookings
-- ==========================================================================
begin;
-- Move an anonymous guest's bookings into the account they sign in to.
--
-- A live-mode tourist is an anonymous Supabase user. Signing in to an existing account replaces
-- that session, and the bookings stay on the anonymous user id, which only that phone's storage can
-- reach. The Edge Function that calls this (not yet written; it needs a real project to verify
-- against) proves control of BOTH identities with verified tokens and passes the two ids here.
--
-- This function therefore TRUSTS ITS ARGUMENTS, exactly like the redeem_voucher_by_hash engine, and
-- so it is executable by the service role only. A caller who could name arbitrary ids could pull
-- any anonymous guest's tickets into their own account. The conditions below are the second line:
-- a bug in the caller can still only move bookings OUT of an anonymous user and INTO an account
-- with a confirmed email, never out of a real account.
--
-- What moves: the guest's bookings, whatever their status (the Stripe webhook confirms by booking
-- id, so a payment that lands after the move still lands on the right booking), and the vouchers
-- issued to them. What does not: trips and saved items have uniqueness rules that two users'
-- rows can collide on, and the tourist app builds its Trips from bookings. The anonymous user is
-- left in place, empty.
--
-- Idempotent: once moved there is nothing left to move, so a second call returns 0 and writes no
-- audit row. Returns the number of bookings moved.

create or replace function transfer_guest_bookings(p_from uuid, p_to uuid)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  from_anonymous boolean;
  to_anonymous   boolean;
  to_confirmed   timestamptz;
  moved_ids      uuid[];
  moved_vouchers integer;
begin
  if p_from is null or p_to is null then
    raise exception 'transfer_guest_bookings: both users are required';
  end if;
  if p_from = p_to then
    raise exception 'transfer_guest_bookings: source and target are the same user';
  end if;

  select u.is_anonymous into from_anonymous from auth.users u where u.id = p_from;
  if not found then
    raise exception 'transfer_guest_bookings: source user does not exist';
  end if;
  if from_anonymous is not true then
    raise exception 'transfer_guest_bookings: source is not an anonymous guest';
  end if;

  select u.is_anonymous, u.email_confirmed_at into to_anonymous, to_confirmed
    from auth.users u where u.id = p_to;
  if not found then
    raise exception 'transfer_guest_bookings: target user does not exist';
  end if;
  if to_anonymous is not false or to_confirmed is null then
    raise exception 'transfer_guest_bookings: target is not an account with a confirmed email';
  end if;

  with moved as (
    update bookings set user_id = p_to where user_id = p_from returning id
  )
  select coalesce(array_agg(id), '{}') into moved_ids from moved;

  update vouchers set user_id = p_to where user_id = p_from;
  get diagnostics moved_vouchers = row_count;

  if coalesce(array_length(moved_ids, 1), 0) > 0 then
    insert into audit_logs (actor_user_id, action, entity_type, entity_id, before, after, reason)
    values (
      p_to,
      'guest_bookings_transferred',
      'profiles',
      p_to,
      jsonb_build_object('from_user', p_from, 'booking_ids', to_jsonb(moved_ids)),
      jsonb_build_object('to_user', p_to, 'bookings', array_length(moved_ids, 1), 'vouchers', moved_vouchers),
      'anonymous guest signed in to an existing account'
    );
  end if;

  return coalesce(array_length(moved_ids, 1), 0);
end;
$$;

-- Both lines are needed: a PUBLIC grant applies to every role, and Supabase also grants EXECUTE to
-- anon directly on new functions. Revoking from one and not the other reads as a fix and changes
-- nothing. Only the Edge Function, running as service_role, may call this.
revoke execute on function transfer_guest_bookings(uuid, uuid) from public;
revoke execute on function transfer_guest_bookings(uuid, uuid) from anon;
revoke execute on function transfer_guest_bookings(uuid, uuid) from authenticated;
grant execute on function transfer_guest_bookings(uuid, uuid) to service_role;

comment on function transfer_guest_bookings(uuid, uuid) is
  'Moves an anonymous guest''s bookings and vouchers to an account with a confirmed email. Trusts its arguments: service_role only.';
commit;

-- ==========================================================================
-- PART 12: 20261022000002_bookings_ticket_token_column_privilege
-- ==========================================================================
begin;
-- Clients cannot read bookings.ticket_token.
--
-- The token is the credential behind the QR at the gate. `bookings_self_read` lets the owner, ANY
-- member of the vendor, and admins read a booking row, and RLS is per-row, so each of them also got
-- the token: vendor staff without can_scan_vouchers could read every token for their vendor, and a
-- guest could read the token of their own cancelled booking straight from the table, bypassing the
-- status rule in my_bookings(). Nothing a client does needs the column: my_bookings() (security
-- definer) returns it to the owner when the booking is confirmed or completed, and the Edge
-- Functions read it as service_role.
--
-- A column privilege is the only per-column control Postgres offers. It cannot be applied as a
-- plain `revoke select (ticket_token)`: while a table-level SELECT exists, that revoke does
-- nothing. So the table-level grant is revoked and every OTHER column is granted back.
--
-- !! THE TRAP: columns added to bookings after this migration are NOT readable by anon or
-- !! authenticated until they are granted. A new migration that adds a column must also say:
-- !!
-- !!     grant select (new_column) on bookings to anon, authenticated;
-- !!
-- !! or withhold it on purpose by adding it to `withheld` in supabase/tests/
-- !! bookings_column_privileges.test.sql. That test fails until one of the two is done. Forgetting
-- !! shows up as "permission denied for table bookings" the first time a client selects `*` or the
-- !! new column; the test turns it into a failure at review time instead.
-- !!
-- !! `select *` from a client is now refused outright (it includes ticket_token). Name the columns.
--
-- Row-level security is unchanged and still decides WHICH rows. Policies on other tables that read
-- bookings as the caller (booking_guests_read, payments_self_read, reviews_self_write) use only
-- id, user_id, vendor_org_id and status, all of which stay readable.

revoke select on bookings from anon, authenticated;

grant select (
  id,
  user_id,
  vendor_org_id,
  experience_id,
  availability_slot_id,
  promotion_id,
  reference,
  status,
  currency,
  subtotal_minor,
  discount_minor,
  tax_minor,
  service_fee_minor,
  total_minor,
  commission_minor,
  seats,
  idempotency_key,
  cancelled_at,
  cancellation_reason,
  completed_at,
  created_at,
  updated_at
) on bookings to anon, authenticated;

comment on column bookings.ticket_token is
  'The QR credential. Not readable by anon or authenticated (column privilege); my_bookings() returns it to the owner at confirmed/completed. See 20261022000002.';
commit;

-- ==========================================================================
-- PART 13: 20261026000001_storage_policies_complete
-- ==========================================================================
begin;
-- Storage policies: close the gaps found when verifying staging-2 (2026-10-26).
--
-- 1. experience-media had no UPDATE policy, so an upload with `upsert: true` (overwrite a listing
--    photo) failed for every vendor.
-- 2. experience-media let ANY vendor member write, but the experience_media table (and experiences)
--    require is_vendor_listing_manager. Staff without can_manage_listings could put files in a
--    listing's folder that they could not reference. Storage now follows the same rule.
-- 3. vendor-documents had no UPDATE or DELETE, so a vendor could never replace a wrong licence
--    scan. Replacing and removing is allowed only while the org is still being reviewed: once a
--    vendor is approved, suspended or rejected the evidence is frozen and only an admin can change
--    it.
--
-- No vendor exists yet, so nothing depends on the old behaviour.
--
-- Guarded like 20260802000011_storage.sql: a no-op where the storage schema is absent (the local
-- Postgres harness). Nothing under supabase/tests can exercise these policies. They were verified
-- on staging with a rolled-back transaction as an authenticated vendor member and as a stranger.

create or replace function vendor_documents_editable(org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from vendor_organizations o
    where o.id = org_id
      and o.status in ('draft', 'pending_review', 'changes_requested')
  );
$$;

comment on function vendor_documents_editable(uuid) is
  'True while the org is still in onboarding review. Evidence files are frozen after that.';

revoke execute on function vendor_documents_editable(uuid) from public, anon;
grant execute on function vendor_documents_editable(uuid) to authenticated;

do $$
begin
  if to_regclass('storage.objects') is null then
    raise notice 'storage schema not present — skipping storage policies (non-Supabase environment)';
    return;
  end if;

  -- experience-media: listing managers (or an admin) write; the folder is the vendor org id.
  execute $p$ drop policy if exists experience_media_vendor_write on storage.objects $p$;
  execute $p$ drop policy if exists experience_media_vendor_delete on storage.objects $p$;

  execute $p$
    create policy experience_media_vendor_write on storage.objects
      for insert to authenticated
      with check (
        bucket_id = 'experience-media'
        and (is_vendor_listing_manager((storage.foldername(name))[1]::uuid) or is_admin())
      );
  $p$;

  execute $p$
    create policy experience_media_vendor_update on storage.objects
      for update to authenticated
      using (
        bucket_id = 'experience-media'
        and (is_vendor_listing_manager((storage.foldername(name))[1]::uuid) or is_admin())
      )
      with check (
        bucket_id = 'experience-media'
        and (is_vendor_listing_manager((storage.foldername(name))[1]::uuid) or is_admin())
      );
  $p$;

  execute $p$
    create policy experience_media_vendor_delete on storage.objects
      for delete to authenticated
      using (
        bucket_id = 'experience-media'
        and (is_vendor_listing_manager((storage.foldername(name))[1]::uuid) or is_admin())
      );
  $p$;

  -- vendor-documents: replace or remove while in review; admins always.
  execute $p$
    create policy vendor_documents_member_update on storage.objects
      for update to authenticated
      using (
        bucket_id = 'vendor-documents'
        and (
          (is_vendor_member((storage.foldername(name))[1]::uuid)
             and vendor_documents_editable((storage.foldername(name))[1]::uuid))
          or is_admin()
        )
      )
      with check (
        bucket_id = 'vendor-documents'
        and (
          (is_vendor_member((storage.foldername(name))[1]::uuid)
             and vendor_documents_editable((storage.foldername(name))[1]::uuid))
          or is_admin()
        )
      );
  $p$;

  execute $p$
    create policy vendor_documents_member_delete on storage.objects
      for delete to authenticated
      using (
        bucket_id = 'vendor-documents'
        and (
          (is_vendor_member((storage.foldername(name))[1]::uuid)
             and vendor_documents_editable((storage.foldername(name))[1]::uuid))
          or is_admin()
        )
      );
  $p$;
end
$$;
commit;

-- ==========================================================================
-- PART 14: 20261029000001_guard_listing_review_fields
-- ==========================================================================
begin;
-- Only an admin may approve a listing.
--
-- `experiences.status` is the gate the public read policy checks, so whoever can write it decides
-- what tourists see. `experiences_vendor_insert` and `experiences_vendor_update` (20261019000001)
-- let an owner, or staff with can_manage_listings, write any column on their own rows, and RLS has
-- no column-level control. A vendor could therefore create a listing as 'approved' or flip a draft
-- to 'approved', skipping moderation entirely. Verified on staging before this migration: as the
-- owner of an organisation, `insert into experiences (…, status) values (…, 'approved')` succeeded.
--
-- Same fix and same reasoning as `guard_vendor_review_fields()` for organisations: a trigger,
-- because the rule is per-column and the caller's identity is only visible to a function.
--
-- What a vendor may do, because the portal needs it:
--   create a listing                         → only as 'draft'
--   draft / rejected → pending_review        submit for review
--   pending_review / rejected → draft        withdraw, or rework after a rejection
--   approved → unpublished                   take a live listing down
--   unpublished → pending_review / draft     coming back is a new review, not a self-service switch
-- Everything else is refused, and so is any write to review_notes, reviewed_by or reviewed_at.
--
-- Not covered here: editing the content of an already-approved listing does not send it back to
-- review. That is a product decision, not a privilege one; see open-decisions.

create or replace function guard_listing_review_fields()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- No end-user context: a service-role caller (Edge Function, migration, seed). Inside the trust
  -- boundary, as for organisations.
  if auth.uid() is null then
    return new;
  end if;

  if is_admin() then
    -- The console must not be trusted to name the reviewer. Stamp it from the identity.
    if tg_op = 'UPDATE' and new.status is distinct from old.status then
      new.reviewed_by := auth.uid();
      new.reviewed_at := now();
    end if;
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'a vendor may only create a listing as a draft';
    end if;
    if new.review_notes is not null or new.reviewed_by is not null or new.reviewed_at is not null then
      raise exception 'only a platform administrator may write a listing''s review fields';
    end if;
    return new;
  end if;

  if new.review_notes is distinct from old.review_notes
     or new.reviewed_by is distinct from old.reviewed_by
     or new.reviewed_at is distinct from old.reviewed_at
  then
    raise exception 'only a platform administrator may write a listing''s review fields';
  end if;

  if new.status is distinct from old.status
     and (old.status, new.status) not in (
       ('draft',          'pending_review'),
       ('rejected',       'pending_review'),
       ('pending_review', 'draft'),
       ('rejected',       'draft'),
       ('approved',       'unpublished'),
       ('unpublished',    'pending_review'),
       ('unpublished',    'draft')
     )
  then
    raise exception 'a vendor cannot move a listing from % to %', old.status, new.status;
  end if;

  return new;
end;
$$;

comment on function guard_listing_review_fields() is
  'Blocks vendor writes that approve a listing or touch its review fields; stamps the reviewer for admins. RLS cannot express a per-column rule.';

create trigger experiences_review_guard
  before insert or update on experiences
  for each row execute function guard_listing_review_fields();
commit;

-- ==========================================================================
-- PART 15: 20261029000002_guard_slot_booked_count
-- ==========================================================================
begin;
-- A vendor must not write `availability_slots.booked_count`.
--
-- `booked_count` is the seat counter that stops a boat being oversold. It is maintained by
-- reserve_availability() and release_availability(), which take a row lock (AD-03) and were taken
-- off the public API in 20261019000002 for exactly that reason. But `availability_slots_vendor_insert`
-- and `availability_slots_vendor_update` (20261019000001) cover every column, so a vendor with
-- listing-manage rights could write the counter directly: lower it with bookings standing, and the
-- next guest is sold a seat that is already taken.
--
-- Same shape as the other two guards (vendor review fields, listing review fields): a trigger,
-- because the rule is per-column and RLS is per-row.
--
-- Capacity and status stay vendor-writable. Capacity is the vendor's own number and
-- `availability_slots_not_oversold` already refuses one below what is sold; status ('closed',
-- 'cancelled') is how a vendor stops sales on a departure.

create or replace function guard_availability_booked_count()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- No end-user context: the service role the booking Edge Functions run as. Admins may correct a
  -- counter by hand.
  if auth.uid() is null or is_admin() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.booked_count <> 0 then
      raise exception 'booked_count is maintained by the booking system, not by vendors';
    end if;
  elsif new.booked_count is distinct from old.booked_count then
    raise exception 'booked_count is maintained by the booking system, not by vendors';
  end if;

  return new;
end;
$$;

comment on function guard_availability_booked_count() is
  'Blocks vendor writes to availability_slots.booked_count. RLS cannot express a per-column rule.';

create trigger availability_slots_booked_count_guard
  before insert or update on availability_slots
  for each row execute function guard_availability_booked_count();
commit;

-- ==========================================================================
-- PART 16: 20261029000003_vendor_document_requirements
-- ==========================================================================
begin;
-- Vendor documents: expiry and number columns, a kind format, and a guard on review fields.
--
-- `vendor_documents` already existed for onboarding evidence, but nothing used it, and two things
-- were missing for it to carry real licences.
--
-- 1. Licences lapse and have numbers an admin can check against a public list (Barbados publishes
--    its licensed operators each February; TPDCo lists Jamaican entities). `expires_on` and
--    `document_number` hold those. Renewals are new rows: the newest row per `kind` is current
--    (see requirementStatuses in packages/types/src/vendorDocuments.ts), and the old ones stay as
--    the audit trail, so there is deliberately no member UPDATE or DELETE policy.
--
-- 2. `vendor_documents_member_write` is `for insert with check (is_vendor_member(vendor_org_id))`
--    and says nothing about columns, so a member could insert a row already marked `accepted`, or
--    name any reviewer, and approve their own evidence. Same shape as the organisation, listing and
--    slot guards: a trigger, because the rule is per-column and RLS is per-row.
--
-- `kind` is the requirement key from the shared registry ('jm.water_sports_licence'). The format
-- check keeps it a key and nothing else; which keys exist is the registry's business, not the
-- database's, so adding a requirement needs no migration.

alter table vendor_documents
  add column document_number text,
  add column expires_on date;

alter table vendor_documents
  add constraint vendor_documents_kind_format check (kind ~ '^[a-z0-9_.]{1,80}$'),
  add constraint vendor_documents_number_length check (document_number is null or char_length(document_number) <= 80);

create or replace function guard_vendor_document_review_fields()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- No end-user context: the service role. Inside the trust boundary, as for the other guards.
  if auth.uid() is null then
    return new;
  end if;

  if is_admin() then
    -- The console must not be trusted to name the reviewer. Stamp it from the identity.
    if tg_op = 'UPDATE' and new.review_state is distinct from old.review_state then
      new.reviewed_by := auth.uid();
      new.reviewed_at := now();
    end if;
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.review_state <> 'pending'
       or new.review_notes is not null
       or new.reviewed_by is not null
       or new.reviewed_at is not null
    then
      raise exception 'a vendor cannot review its own documents';
    end if;
    -- Who uploaded is a fact about the caller, not something to take from the row.
    new.uploaded_by := auth.uid();
  elsif new.review_state is distinct from old.review_state
     or new.review_notes is distinct from old.review_notes
     or new.reviewed_by is distinct from old.reviewed_by
     or new.reviewed_at is distinct from old.reviewed_at
  then
    raise exception 'a vendor cannot review its own documents';
  end if;

  return new;
end;
$$;

comment on function guard_vendor_document_review_fields() is
  'Blocks vendor writes to a document''s review fields, stamps uploaded_by, and stamps the reviewer for admins.';

create trigger vendor_documents_review_guard
  before insert or update on vendor_documents
  for each row execute function guard_vendor_document_review_fields();
commit;

-- ==========================================================================
-- PART 17: 20261031000001_guard_promotion_review_fields
-- ==========================================================================
begin;
-- Only an admin may approve a promotion, and only the system may move its issued counter.
--
-- `promotions.approval_state` is what `promotions_public_read` checks, so whoever can write it
-- decides which offers tourists see. `promotions_vendor_all` (20260802000010) lets any member of
-- the vendor organisation write every column of their own rows, and RLS has no column-level
-- control. A vendor could therefore insert a promotion as 'approved', or flip their own to it,
-- skipping oversight entirely. The same policy covers `issued_count`, the counter behind
-- `inventory_limit`: lower it and the inventory check no longer stops anything. And `is_demo`
-- would let a vendor label a row however suits them.
--
-- Same fix and same reasoning as `guard_listing_review_fields()`: a trigger, because the rule is
-- per-column and the caller's identity is only visible to a function.
--
-- What a vendor may do, because the portal needs it:
--   create a promotion                       → only as 'pending', with issued_count 0
--   rejected → pending                       rework after a rejection
--   approved → disabled                      take their own live offer down
--   disabled → pending                       coming back is a new review, not a self-service switch
-- Everything else is refused, and so is any write to reviewed_by, reviewed_at, issued_count or
-- is_demo. Value, dates, terms and inventory_limit stay vendor-writable.
--
-- Not covered here: editing the value, dates or terms of an already-approved promotion does not
-- send it back to review. That is a product decision, not a privilege one, as for listings.
--
-- Nothing writes `issued_count` yet. When voucher issuing does, it must run as the service role
-- (no auth.uid()), which this guard lets through.

create or replace function guard_promotion_review_fields()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- No end-user context: a service-role caller (Edge Function, migration, seed). Inside the trust
  -- boundary, as for listings.
  if auth.uid() is null then
    return new;
  end if;

  if is_admin() then
    -- The console must not be trusted to name the reviewer. Stamp it from the identity.
    if tg_op = 'UPDATE' and new.approval_state is distinct from old.approval_state then
      new.reviewed_by := auth.uid();
      new.reviewed_at := now();
    end if;
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.approval_state <> 'pending' then
      raise exception 'a vendor may only create a promotion as pending';
    end if;
    if new.reviewed_by is not null or new.reviewed_at is not null then
      raise exception 'only a platform administrator may write a promotion''s review fields';
    end if;
    if new.issued_count <> 0 then
      raise exception 'issued_count is maintained by the system, not by vendors';
    end if;
    if new.is_demo then
      raise exception 'only a platform administrator may mark a promotion as demo';
    end if;
    return new;
  end if;

  if new.reviewed_by is distinct from old.reviewed_by
     or new.reviewed_at is distinct from old.reviewed_at
  then
    raise exception 'only a platform administrator may write a promotion''s review fields';
  end if;

  if new.issued_count is distinct from old.issued_count then
    raise exception 'issued_count is maintained by the system, not by vendors';
  end if;

  if new.is_demo is distinct from old.is_demo then
    raise exception 'only a platform administrator may mark a promotion as demo';
  end if;

  if new.approval_state is distinct from old.approval_state
     and (old.approval_state, new.approval_state) not in (
       ('rejected', 'pending'),
       ('approved', 'disabled'),
       ('disabled', 'pending')
     )
  then
    raise exception 'a vendor cannot move a promotion from % to %', old.approval_state, new.approval_state;
  end if;

  return new;
end;
$$;

comment on function guard_promotion_review_fields() is
  'Blocks vendor writes that approve a promotion or touch its review fields, issued_count or is_demo; stamps the reviewer for admins. RLS cannot express a per-column rule.';

create trigger promotions_review_guard
  before insert or update on promotions
  for each row execute function guard_promotion_review_fields();
commit;

-- ==========================================================================
-- PART 18: 20261031000002_audit_promotion_approval
-- ==========================================================================
begin;
-- Log every change to a promotion's approval state.
--
-- `audit_status_change()` (20260802000009) covers vendor organisations and listings, but it reads
-- `status` and `review_notes`, and `promotions` has neither: its gate is `approval_state`. Without
-- this trigger a vendor taking their own live offer down (allowed by guard_promotion_review_fields)
-- would leave no trace, and an admin decision would be logged only if the console remembers to.
-- As for the other two tables, the database writes the row so no code path can forget; the console
-- adds its own row through write_audit_log() to carry the reason.
--
-- The entity type is the table name, matching the trigger rows for organisations and listings.

create or replace function audit_promotion_approval()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if old.approval_state is distinct from new.approval_state then
    insert into audit_logs (actor_user_id, action, entity_type, entity_id, before, after)
    values (
      auth.uid(),
      'promotions.approval_state_changed',
      'promotions',
      new.id,
      jsonb_build_object('approval_state', old.approval_state),
      jsonb_build_object('approval_state', new.approval_state)
    );
  end if;
  return new;
end;
$$;

comment on function audit_promotion_approval() is
  'Writes an audit_logs row when promotions.approval_state changes. audit_status_change() cannot: promotions has no status or review_notes column.';

create trigger promotions_audit
  after update of approval_state on promotions
  for each row execute function audit_promotion_approval();
commit;

-- ==========================================================================
-- PART 19: 20261031000003_claim_promotion_voucher
-- ==========================================================================
begin;
-- Issue a voucher for a standalone promotion, and count it, in one step.
--
-- `issued_count` is the counter behind `inventory_limit`. 20261031000001 made it writable only by
-- the system; this is the system writing it. Counting and inserting are one function so a voucher
-- cannot exist without the count, or the count without the voucher, and so the last unit of
-- inventory can be claimed by exactly one caller.
--
-- The promotion row is locked first (`for update`). Every claim of the same promotion queues on
-- that lock, so the checks below read a count nobody else is changing: two guests racing for the
-- last unit are decided one after the other, not both let through. The table's own
-- `issued_count <= inventory_limit` check is the last line of defence, not the first.
--
-- Outcomes, text so the Edge Function can map them without parsing an error:
--   claimed          a voucher was inserted and issued_count moved by one
--   already_claimed  the guest already holds a live voucher for this promotion (same states as
--                    `claimedPromotionIds`), so nothing is counted twice
--   sold_out         inventory_limit reached
--   not_available    no such promotion, not approved, or outside its window
--
-- Eligibility (consent, geofence, vendor status) stays in `eligible-offer`; this function only
-- guards what must be atomic with the count. Executable by the service role only, like
-- `reserve_availability`, and revoked from PUBLIC *and* anon/authenticated: the PUBLIC grant alone
-- covers every role, so revoking the named roles first would change nothing.

create or replace function claim_promotion_voucher(
  p_promotion_id uuid,
  p_user_id      uuid,
  p_token_hash   text,
  p_valid_until  timestamptz
)
returns table (outcome text, voucher_id uuid)
language plpgsql
security definer
set search_path = public
as $$
declare
  promo promotions%rowtype;
  v_id  uuid;
begin
  select * into promo from promotions where id = p_promotion_id for update;

  if not found
     or promo.approval_state <> 'approved'
     or now() < promo.starts_at
     or now() > promo.ends_at then
    return query select 'not_available'::text, null::uuid;
    return;
  end if;

  if exists (
    select 1 from vouchers
     where promotion_id = p_promotion_id
       and user_id = p_user_id
       and state in ('issued', 'saved', 'attached_to_booking', 'active', 'redeemed')
  ) then
    return query select 'already_claimed'::text, null::uuid;
    return;
  end if;

  if promo.inventory_limit is not null and promo.issued_count >= promo.inventory_limit then
    return query select 'sold_out'::text, null::uuid;
    return;
  end if;

  insert into vouchers (token_hash, user_id, promotion_id, vendor_org_id, valid_until)
  values (p_token_hash, p_user_id, p_promotion_id, promo.vendor_org_id,
          least(p_valid_until, promo.ends_at))
  returning id into v_id;

  update promotions set issued_count = issued_count + 1 where id = p_promotion_id;

  return query select 'claimed'::text, v_id;
end;
$$;

revoke execute on function claim_promotion_voucher(uuid, uuid, text, timestamptz) from public;
revoke execute on function claim_promotion_voucher(uuid, uuid, text, timestamptz) from anon, authenticated;
grant execute on function claim_promotion_voucher(uuid, uuid, text, timestamptz) to service_role;
commit;

-- ==========================================================================
-- PART 20: 20261102000001_consent_events
-- ==========================================================================
begin;
-- Provable consent (GDPR Art 7(1)): who agreed to what, when, and to which wording.
--
-- `profiles.location_consent`, `offer_consent` and `notification_consent` say what the guest chose
-- last. They cannot say when, to what text, or that the choice was ever withdrawn. A regulator or a
-- guest can ask; this table answers. One row per change, never edited.
--
-- Writes go through record_consent() only. It updates the flag and appends the event in one
-- transaction, so the flag and its proof cannot disagree, and a guest cannot flip a flag directly:
-- guard_profile_consent() refuses an end-user UPDATE of any consent column made outside the
-- function. Service-role code (migrations, seeds, Edge Functions) is inside the trust boundary and
-- is not blocked, but it leaves no event; no Edge Function writes consent today.
--
-- Erasure: rows cascade with the profile. Whether proof of consent must outlive an erased account
-- is a question for counsel (docs/data-inventory.md), so nothing here prevents or forces it.

create table consent_events (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references profiles(id) on delete cascade,
  purpose         text not null check (purpose in ('location', 'offers', 'notifications')),
  granted         boolean not null,
  -- Identifies the exact text the guest saw. The client names it; the text itself is in its source.
  wording_version text not null check (length(btrim(wording_version)) between 1 and 64),
  created_at      timestamptz not null default now()
);

create index consent_events_user_idx on consent_events (user_id, created_at desc);

-- Editing a row would rewrite what was agreed. Deletes are left open on purpose: they are how an
-- erased profile takes its rows with it (a cascade fires this kind of trigger too).
create trigger consent_events_no_update
  before update on consent_events
  for each row execute function forbid_mutation();

alter table consent_events enable row level security;

create policy consent_events_self_read on consent_events
  for select to authenticated
  using (user_id = auth.uid());

create policy consent_events_admin_read on consent_events
  for select to authenticated
  using (is_admin());

-- No insert policy: only record_consent() (security definer) writes.

create or replace function record_consent(p_purpose text, p_granted boolean, p_wording_version text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  uid     uuid := auth.uid();
  current boolean;
begin
  if uid is null then
    raise exception 'sign in to record consent';
  end if;
  if p_purpose not in ('location', 'offers', 'notifications') then
    raise exception 'unknown consent purpose';
  end if;
  if p_granted is null then
    raise exception 'consent must be granted or withdrawn';
  end if;
  if p_wording_version is null or length(btrim(p_wording_version)) not between 1 and 64 then
    raise exception 'a wording version is required';
  end if;

  select case p_purpose
           when 'location' then location_consent
           when 'offers' then offer_consent
           else notification_consent
         end
    into current
    from profiles where id = uid for update;
  if not found then
    raise exception 'no profile for this user';
  end if;

  -- The app re-states the guest's answer whenever it starts. A restatement is not a new consent.
  if current = p_granted then
    return;
  end if;

  perform set_config('cvip.consent_rpc', 'on', true);
  update profiles set
    location_consent     = case when p_purpose = 'location' then p_granted else location_consent end,
    offer_consent        = case when p_purpose = 'offers' then p_granted else offer_consent end,
    notification_consent = case when p_purpose = 'notifications' then p_granted else notification_consent end
  where id = uid;
  perform set_config('cvip.consent_rpc', 'off', true);

  insert into consent_events (user_id, purpose, granted, wording_version)
  values (uid, p_purpose, p_granted, btrim(p_wording_version));
end;
$$;

comment on function record_consent(text, boolean, text) is
  'The only way an end user changes a consent flag. Updates the flag and appends a consent_events row atomically; a restatement of the current value writes nothing.';

revoke execute on function record_consent(text, boolean, text) from public, anon;
grant execute on function record_consent(text, boolean, text) to authenticated;

create or replace function guard_profile_consent()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is not null
     and current_setting('cvip.consent_rpc', true) is distinct from 'on'
     and (new.location_consent is distinct from old.location_consent
          or new.offer_consent is distinct from old.offer_consent
          or new.notification_consent is distinct from old.notification_consent) then
    raise exception 'consent changes go through record_consent()';
  end if;
  return new;
end;
$$;

create trigger profiles_consent_guard
  before update on profiles
  for each row execute function guard_profile_consent();
commit;

-- ==========================================================================
-- PART 21: 20261103000001_erasure_and_export
-- ==========================================================================
begin;
-- A guest can download their data and ask for it to be erased (GDPR Art 15, 17, 20).
--
-- export_my_data()  everything this system holds about the caller, as one JSON document.
-- erase_my_data()   removes or scrubs what is not under a legal retention duty, and says what stays.
--
-- What erasure does NOT remove, on purpose, so the guest is told rather than surprised:
--   * bookings and payments: accounting and dispute records; the guest's free text is scrubbed
--     (attendee names, cancellation reason) and the rows stay, tied to a profile that no longer
--     holds a name. Retention periods are for counsel (docs/data-inventory.md).
--   * consent_events: proof that consent was given or withdrawn, kept to defend a claim
--     (Art 17(3)(e)). Erasure appends a withdrawal for every flag that was on.
--   * the sign-in itself: removing an auth user needs the Auth admin API, so the account row stays
--     as an empty shell until an Edge Function deletes it. A guest with no bookings loses nothing
--     by that; a guest with bookings cannot be deleted at all (bookings.user_id is ON DELETE
--     RESTRICT, deliberately).
-- Staff (vendor or admin roles) hold business data this function does not model; their accounts
-- are handled by an administrator.

create or replace function export_my_data()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  uid uuid := auth.uid();
  result jsonb;
begin
  if uid is null then
    raise exception 'sign in to export your data';
  end if;

  select jsonb_build_object(
    'exported_at', now(),
    'profile', (select to_jsonb(p) from profiles p where p.id = uid),
    'consent_events', coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at) from consent_events c where c.user_id = uid), '[]'),
    'saved_items', coalesce((select jsonb_agg(to_jsonb(s)) from saved_items s where s.user_id = uid), '[]'),
    'trips', coalesce((select jsonb_agg(to_jsonb(t) || jsonb_build_object(
        'items', coalesce((select jsonb_agg(to_jsonb(i) order by i.sort_order) from trip_items i where i.trip_id = t.id), '[]')))
      from trips t where t.user_id = uid), '[]'),
    'bookings', coalesce((select jsonb_agg(to_jsonb(b) || jsonb_build_object(
        'guests', coalesce((select jsonb_agg(to_jsonb(g)) from booking_guests g where g.booking_id = b.id), '[]'),
        'payments', coalesce((select jsonb_agg(to_jsonb(y)) from payments y where y.booking_id = b.id), '[]')))
      from bookings b where b.user_id = uid), '[]'),
    'reviews', coalesce((select jsonb_agg(to_jsonb(r)) from reviews r where r.user_id = uid), '[]'),
    'notifications', coalesce((select jsonb_agg(to_jsonb(n)) from notifications n where n.user_id = uid), '[]'),
    'ai_conversations', coalesce((select jsonb_agg(to_jsonb(a)) from ai_conversations a where a.user_id = uid), '[]'),
    'offers_shown', coalesce((select jsonb_agg(to_jsonb(m)) from promotion_impressions m where m.user_id = uid), '[]'),
    'vouchers', coalesce((select jsonb_agg(to_jsonb(v)) from vouchers v where v.user_id = uid), '[]')
  ) into result;

  return result;
end;
$$;

comment on function export_my_data() is
  'Everything held about the caller, as JSON. Reads only rows where the caller is the subject.';

create or replace function erase_my_data()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  uid uuid := auth.uid();
  prof profiles%rowtype;
  kept_bookings integer;
begin
  if uid is null then
    raise exception 'sign in to erase your data';
  end if;

  select * into prof from profiles where id = uid for update;
  if not found then
    raise exception 'no profile for this user';
  end if;
  if prof.role <> 'tourist' then
    raise exception 'staff accounts are erased by an administrator';
  end if;

  delete from ai_conversations where user_id = uid;
  delete from saved_items where user_id = uid;
  delete from trips where user_id = uid;
  delete from notifications where user_id = uid;
  delete from promotion_impressions where user_id = uid;
  delete from reviews where user_id = uid;
  update vouchers set user_id = null where user_id = uid and booking_id is null;

  update booking_guests set guest_name = null
   where booking_id in (select id from bookings where user_id = uid);
  update bookings set cancellation_reason = null where user_id = uid;

  -- Withdraw every consent that was on, and leave the proof of it.
  insert into consent_events (user_id, purpose, granted, wording_version)
  select uid, f.purpose, false, 'erasure'
    from (values ('location', prof.location_consent),
                 ('offers', prof.offer_consent),
                 ('notifications', prof.notification_consent)) as f(purpose, was_on)
   where f.was_on;

  perform set_config('cvip.consent_rpc', 'on', true);
  update profiles set
    display_name = null,
    interests = '{}',
    party_size = null,
    selected_island_id = null,
    selected_destination_id = null,
    location_consent = false,
    offer_consent = false,
    notification_consent = false
  where id = uid;
  perform set_config('cvip.consent_rpc', 'off', true);

  select count(*) into kept_bookings from bookings where user_id = uid;

  return jsonb_build_object(
    'erased', true,
    'bookings_retained', kept_bookings,
    'account_removable', kept_bookings = 0
  );
end;
$$;

comment on function erase_my_data() is
  'Erases or scrubs the caller''s personal data; keeps bookings, payments and consent proof. Staff accounts are refused.';

revoke execute on function export_my_data() from public, anon;
revoke execute on function erase_my_data() from public, anon;
grant execute on function export_my_data() to authenticated;
grant execute on function erase_my_data() to authenticated;
commit;

-- ==========================================================================
-- PART 22: 20261103000002_privacy_requests
-- ==========================================================================
begin;
-- A record that each access or erasure request was honoured (GDPR Art 5(2), accountability).
--
-- Until now erase_my_data() left no trace of itself beyond the consent withdrawals, so the
-- controller could not show a regulator, or the guest, that a request was received and answered.
-- This table is that record. It holds a pseudonymous subject id, the kind of request, when, and a
-- counts-only outcome. It deliberately has NO foreign key to profiles: erasure and any later
-- account removal must not delete the evidence that erasure happened. It holds no names, no
-- exported content and no free text.
--
-- Both functions now write their own row in the same transaction as the work, so a request cannot
-- be honoured without being recorded. export_my_data() therefore stops being STABLE.
--
-- Retention of these rows is for counsel (docs/data-inventory.md). Backups: an erased guest
-- reappears if a backup is restored; replaying this log is how the erasure is re-applied.

create table privacy_requests (
  id           uuid primary key default gen_random_uuid(),
  subject_id   uuid not null,
  request_type text not null check (request_type in ('export', 'erasure')),
  received_at  timestamptz not null default now(),
  outcome      jsonb not null default '{}'::jsonb
);

create index privacy_requests_subject_idx on privacy_requests (subject_id, received_at desc);

create trigger privacy_requests_no_update
  before update on privacy_requests
  for each row execute function forbid_mutation();

alter table privacy_requests enable row level security;

create policy privacy_requests_self_read on privacy_requests
  for select to authenticated
  using (subject_id = auth.uid());

create policy privacy_requests_admin_read on privacy_requests
  for select to authenticated
  using (is_admin());

-- No insert policy: only the two functions below write.

create or replace function export_my_data()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  uid uuid := auth.uid();
  result jsonb;
begin
  if uid is null then
    raise exception 'sign in to export your data';
  end if;

  select jsonb_build_object(
    'exported_at', now(),
    'profile', (select to_jsonb(p) from profiles p where p.id = uid),
    'consent_events', coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at) from consent_events c where c.user_id = uid), '[]'),
    'saved_items', coalesce((select jsonb_agg(to_jsonb(s)) from saved_items s where s.user_id = uid), '[]'),
    'trips', coalesce((select jsonb_agg(to_jsonb(t) || jsonb_build_object(
        'items', coalesce((select jsonb_agg(to_jsonb(i) order by i.sort_order) from trip_items i where i.trip_id = t.id), '[]')))
      from trips t where t.user_id = uid), '[]'),
    'bookings', coalesce((select jsonb_agg(to_jsonb(b) || jsonb_build_object(
        'guests', coalesce((select jsonb_agg(to_jsonb(g)) from booking_guests g where g.booking_id = b.id), '[]'),
        'payments', coalesce((select jsonb_agg(to_jsonb(y)) from payments y where y.booking_id = b.id), '[]')))
      from bookings b where b.user_id = uid), '[]'),
    'reviews', coalesce((select jsonb_agg(to_jsonb(r)) from reviews r where r.user_id = uid), '[]'),
    'notifications', coalesce((select jsonb_agg(to_jsonb(n)) from notifications n where n.user_id = uid), '[]'),
    'ai_conversations', coalesce((select jsonb_agg(to_jsonb(a)) from ai_conversations a where a.user_id = uid), '[]'),
    'offers_shown', coalesce((select jsonb_agg(to_jsonb(m)) from promotion_impressions m where m.user_id = uid), '[]'),
    'vouchers', coalesce((select jsonb_agg(to_jsonb(v)) from vouchers v where v.user_id = uid), '[]')
  ) into result;

  insert into privacy_requests (subject_id, request_type)
  values (uid, 'export');

  return result;
end;
$$;

