-- ==========================================================================
-- PART 23: 20261103000003_activate_standalone_offer_vouchers
-- ==========================================================================
begin;
-- A claimed standalone offer voucher must be redeemable.
--
-- `claim_promotion_voucher` inserted offer vouchers in the default state 'issued'. The redemption
-- engine only redeems 'active' vouchers, and no path activates an offer voucher that has no
-- booking, so every standalone claim scanned as not_yet_valid at the door. Found by
-- `supabase/tests/claim_then_redeem.test.sql`, which joins the two halves for the first time.
--
-- Fix: a promotion with requires_booking = false yields an 'active' voucher at claim. One with
-- requires_booking = true is unchanged ('issued', until its booking attaches it). Existing
-- vouchers in that state are activated below; 'issued' to 'active' is a legal transition.
-- Grants are unchanged by create or replace.

create or replace function claim_promotion_voucher(
  p_promotion_id uuid,
  p_user_id      uuid,
  p_token_hash   text,
  p_valid_until  timestamptz
)
returns table (outcome text, voucher_id uuid)
language plpgsql
security definer
set search_path = public
as $$
declare
  promo promotions%rowtype;
  v_id  uuid;
begin
  select * into promo from promotions where id = p_promotion_id for update;

  if not found
     or promo.approval_state <> 'approved'
     or now() < promo.starts_at
     or now() > promo.ends_at then
    return query select 'not_available'::text, null::uuid;
    return;
  end if;

  if exists (
    select 1 from vouchers
     where promotion_id = p_promotion_id
       and user_id = p_user_id
       and state in ('issued', 'saved', 'attached_to_booking', 'active', 'redeemed')
  ) then
    return query select 'already_claimed'::text, null::uuid;
    return;
  end if;

  if promo.inventory_limit is not null and promo.issued_count >= promo.inventory_limit then
    return query select 'sold_out'::text, null::uuid;
    return;
  end if;

  -- A standalone promotion's voucher is usable at the door as soon as it exists. The scanner only
  -- redeems 'active' vouchers, and nothing else activates an offer voucher with no booking, so the
  -- default 'issued' made every standalone claim scan as not_yet_valid. A promotion that requires a
  -- booking stays 'issued' until the booking attaches it.
  insert into vouchers (token_hash, user_id, promotion_id, vendor_org_id, valid_until, state)
  values (p_token_hash, p_user_id, p_promotion_id, promo.vendor_org_id,
          least(p_valid_until, promo.ends_at),
          case when promo.requires_booking then 'issued'::voucher_state else 'active'::voucher_state end)
  returning id into v_id;

  update promotions set issued_count = issued_count + 1 where id = p_promotion_id;

  return query select 'claimed'::text, v_id;
end;
$$;

update vouchers v
   set state = 'active'
  from promotions p
 where p.id = v.promotion_id
   and v.state = 'issued'
   and v.booking_id is null
   and not p.requires_booking
   and v.valid_until > now();
commit;

-- ==========================================================================
-- PART 24: 20261103000004_redemption_anomalies
-- ==========================================================================
begin;
-- Redemption anomalies (OD-10): flags for an admin to look at. Never changes a redemption result.
--
-- Source is `voucher_redemptions`, which is append-only and logs every scan including failures, so
-- a scanner cannot make their own flags disappear. Four patterns, per docs/redemption-anomalies.md:
--   unknown_token_burst  one scanner, many unknown tokens inside an hour (guessing or forging)
--   wrong_vendor_repeat  one scanner, repeated wrong_vendor inside a day
--   voucher_rescanned    one voucher scanned again after it was redeemed (shared screenshot)
--   scan_rate            one scanner, many ok scans inside a minute (scanning with no guests)
--
-- Safeguards, each proven by a test that fails without it:
--   * Thresholds live in platform_settings, written by super_admin only (the existing policy), and
--     a trigger rejects a value that is missing, not an integer, below 1 or above a hard ceiling. A
--     threshold cannot be raised high enough to switch a pattern off.
--   * The reader falls back to the default for any single value that is not valid, so a bad row
--     (written around the trigger) tightens nothing and disables nothing.
--   * redemption_anomalies() refuses anyone who is not an admin, and is revoked from public AND anon.

-- --------------------------------------------------------------------------
-- Thresholds
-- --------------------------------------------------------------------------

insert into platform_settings (key, value, description)
values (
  'redemption.anomaly_thresholds',
  '{"unknown_token_per_hour":10,"wrong_vendor_per_day":3,"repeat_scans_per_voucher":2,"ok_scans_per_minute":20}'::jsonb,
  'Redemption anomaly flags (OD-10). Whole numbers, 1 up to a ceiling. A flag is for an admin to review; it never blocks a scan.'
)
on conflict (key) do nothing;

-- Defaults and ceilings in one place, used by both the trigger and the reader.
create or replace function redemption_anomaly_limits()
returns table (name text, default_value integer, ceiling integer)
language sql
immutable
as $$
  select * from (values
    ('unknown_token_per_hour',     10,  50),
    ('wrong_vendor_per_day',        3,  20),
    ('repeat_scans_per_voucher',    2,  10),
    ('ok_scans_per_minute',        20, 100)
  ) as t(name, default_value, ceiling);
$$;

create or replace function assert_redemption_thresholds()
returns trigger
language plpgsql
as $$
declare
  lim record;
  v   jsonb;
begin
  if new.key <> 'redemption.anomaly_thresholds' then
    return new;
  end if;
  if jsonb_typeof(new.value) <> 'object' then
    raise exception 'redemption.anomaly_thresholds must be an object';
  end if;
  if (select count(*) from jsonb_object_keys(new.value)) <> (select count(*) from redemption_anomaly_limits()) then
    raise exception 'redemption.anomaly_thresholds must hold exactly the four known keys';
  end if;
  for lim in select * from redemption_anomaly_limits() loop
    v := new.value -> lim.name;
    if v is null
       or jsonb_typeof(v) <> 'number'
       or (v #>> '{}') !~ '^[0-9]+$'
       or (v #>> '{}')::numeric < 1
       or (v #>> '{}')::numeric > lim.ceiling then
      raise exception '% must be a whole number from 1 to %', lim.name, lim.ceiling;
    end if;
  end loop;
  return new;
end;
$$;

create trigger platform_settings_redemption_thresholds
  before insert or update on platform_settings
  for each row execute function assert_redemption_thresholds();

-- Each value, or its default when the stored one is not valid.
create or replace function redemption_anomaly_thresholds()
returns table (unknown_token_per_hour integer, wrong_vendor_per_day integer,
               repeat_scans_per_voucher integer, ok_scans_per_minute integer)
language sql
stable
security definer
set search_path = public
as $$
  with s as (select value from platform_settings where key = 'redemption.anomaly_thresholds'),
  pick as (
    select l.name,
           case
             when jsonb_typeof(s.value -> l.name) = 'number'
              and (s.value -> l.name) #>> '{}' ~ '^[0-9]+$'
              and ((s.value -> l.name) #>> '{}')::numeric between 1 and l.ceiling
             then ((s.value -> l.name) #>> '{}')::integer
             else l.default_value
           end as v
      from redemption_anomaly_limits() l
      left join s on true
  )
  select
    (select v from pick where name = 'unknown_token_per_hour'),
    (select v from pick where name = 'wrong_vendor_per_day'),
    (select v from pick where name = 'repeat_scans_per_voucher'),
    (select v from pick where name = 'ok_scans_per_minute');
$$;

revoke execute on function redemption_anomaly_thresholds() from public, anon, authenticated;

-- --------------------------------------------------------------------------
-- The flags
-- --------------------------------------------------------------------------

create or replace function redemption_anomalies()
returns table (
  pattern         text,
  scanner_user_id uuid,
  vendor_org_id   uuid,
  voucher_id      uuid,
  scan_count      integer,
  first_at        timestamptz,
  last_at         timestamptz
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  t record;
begin
  if not is_admin() then
    raise exception 'only an admin may read redemption anomalies';
  end if;

  select * into t from redemption_anomaly_thresholds();

  return query
  with recent as (
    select r.* from voucher_redemptions r where r.scanned_at > now() - interval '7 days'
  ),
  unknown_w as (
    select r.scanner_user_id, r.vendor_org_id, r.scanned_at,
           count(*) over (partition by r.scanner_user_id order by r.scanned_at
                          range between interval '1 hour' preceding and current row) as n
      from recent r where r.result = 'unknown_token' and r.scanner_user_id is not null
  ),
  wrong_w as (
    select r.scanner_user_id, r.vendor_org_id, r.scanned_at,
           count(*) over (partition by r.scanner_user_id order by r.scanned_at
                          range between interval '1 day' preceding and current row) as n
      from recent r where r.result = 'wrong_vendor' and r.scanner_user_id is not null
  ),
  rate_w as (
    select r.scanner_user_id, r.vendor_org_id, r.scanned_at,
           count(*) over (partition by r.scanner_user_id order by r.scanned_at
                          range between interval '1 minute' preceding and current row) as n
      from recent r where r.result = 'ok' and r.scanner_user_id is not null
  )
  select 'unknown_token_burst'::text, w.scanner_user_id, (array_agg(w.vendor_org_id))[1], null::uuid,
         max(w.n)::integer, min(w.scanned_at), max(w.scanned_at)
    from unknown_w w where w.n >= t.unknown_token_per_hour group by w.scanner_user_id
  union all
  select 'wrong_vendor_repeat', w.scanner_user_id, (array_agg(w.vendor_org_id))[1], null::uuid,
         max(w.n)::integer, min(w.scanned_at), max(w.scanned_at)
    from wrong_w w where w.n >= t.wrong_vendor_per_day group by w.scanner_user_id
  union all
  select 'scan_rate', w.scanner_user_id, (array_agg(w.vendor_org_id))[1], null::uuid,
         max(w.n)::integer, min(w.scanned_at), max(w.scanned_at)
    from rate_w w where w.n >= t.ok_scans_per_minute group by w.scanner_user_id
  union all
  select 'voucher_rescanned', null::uuid, (array_agg(r.vendor_org_id))[1], r.voucher_id,
         count(*)::integer, min(r.scanned_at), max(r.scanned_at)
    from recent r
   where r.result = 'already_redeemed' and r.voucher_id is not null
   group by r.voucher_id
  having count(*) >= t.repeat_scans_per_voucher
  order by 7 desc;
end;
$$;

comment on function redemption_anomalies() is
  'Open redemption anomaly flags from the last 7 days. Admin only. A flag never changes a scan result.';

revoke execute on function redemption_anomalies() from public, anon;
grant execute on function redemption_anomalies() to authenticated;
commit;

-- ==========================================================================
-- PART 25: 20261103000005_anomaly_reviews
-- ==========================================================================
begin;
-- Mark a redemption flag reviewed, without letting a review silence anything.
--
-- Reviews are append-only rows. A review hides nothing: `redemption_anomalies()` still returns the
-- flag, with who reviewed it and when. It counts as open again the moment a newer scan feeds the
-- same flag, so a flag cannot be closed once and then ignored forever.
--
-- Safeguards, each proven by a test that fails without it:
--   * `review_redemption_anomaly()` is admin only, takes the reviewer from `auth.uid()` (never a
--     parameter), and reviews only a flag that exists right now, recording that flag's own latest
--     scan time. A review cannot be written ahead of time to pre-silence a future flag.
--   * No insert policy: the function is the only writer. Rows cannot be updated or deleted.
--   * The note is capped, so the table cannot become a store of free text.
--   * Ids carry no foreign key on purpose: a foreign key with ON DELETE SET NULL is an update, and
--     the append-only trigger would block the erasure cascade (see data-inventory.md).

create table redemption_anomaly_reviews (
  id              uuid primary key default gen_random_uuid(),
  pattern         text not null check (pattern in
                    ('unknown_token_burst', 'wrong_vendor_repeat', 'voucher_rescanned', 'scan_rate')),
  scanner_user_id uuid,
  voucher_id      uuid,
  flag_last_at    timestamptz not null,
  reviewed_by     uuid not null,
  note            text check (note is null or char_length(note) <= 500),
  reviewed_at     timestamptz not null default now(),
  -- A flag is about a scanner or a voucher, exactly one of them.
  check ((scanner_user_id is null) <> (voucher_id is null))
);

create index redemption_anomaly_reviews_key_idx
  on redemption_anomaly_reviews (pattern, scanner_user_id, voucher_id, flag_last_at desc);

create trigger redemption_anomaly_reviews_no_update
  before update on redemption_anomaly_reviews
  for each row execute function forbid_mutation();

alter table redemption_anomaly_reviews enable row level security;

create policy redemption_anomaly_reviews_admin_read on redemption_anomaly_reviews
  for select to authenticated
  using (is_admin());

-- No insert, update or delete policy: only review_redemption_anomaly() writes.

-- --------------------------------------------------------------------------
-- The flags, as before but internal, so the public reader can add review state
-- --------------------------------------------------------------------------

drop function redemption_anomalies();

create or replace function redemption_flags_raw()
returns table (
  pattern         text,
  scanner_user_id uuid,
  vendor_org_id   uuid,
  voucher_id      uuid,
  scan_count      integer,
  first_at        timestamptz,
  last_at         timestamptz
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  t record;
begin
  select * into t from redemption_anomaly_thresholds();

  return query
  with recent as (
    select r.* from voucher_redemptions r where r.scanned_at > now() - interval '7 days'
  ),
  unknown_w as (
    select r.scanner_user_id, r.vendor_org_id, r.scanned_at,
           count(*) over (partition by r.scanner_user_id order by r.scanned_at
                          range between interval '1 hour' preceding and current row) as n
      from recent r where r.result = 'unknown_token' and r.scanner_user_id is not null
  ),
  wrong_w as (
    select r.scanner_user_id, r.vendor_org_id, r.scanned_at,
           count(*) over (partition by r.scanner_user_id order by r.scanned_at
                          range between interval '1 day' preceding and current row) as n
      from recent r where r.result = 'wrong_vendor' and r.scanner_user_id is not null
  ),
  rate_w as (
    select r.scanner_user_id, r.vendor_org_id, r.scanned_at,
           count(*) over (partition by r.scanner_user_id order by r.scanned_at
                          range between interval '1 minute' preceding and current row) as n
      from recent r where r.result = 'ok' and r.scanner_user_id is not null
  )
  select 'unknown_token_burst'::text, w.scanner_user_id, (array_agg(w.vendor_org_id))[1], null::uuid,
         max(w.n)::integer, min(w.scanned_at), max(w.scanned_at)
    from unknown_w w where w.n >= t.unknown_token_per_hour group by w.scanner_user_id
  union all
  select 'wrong_vendor_repeat', w.scanner_user_id, (array_agg(w.vendor_org_id))[1], null::uuid,
         max(w.n)::integer, min(w.scanned_at), max(w.scanned_at)
    from wrong_w w where w.n >= t.wrong_vendor_per_day group by w.scanner_user_id
  union all
  select 'scan_rate', w.scanner_user_id, (array_agg(w.vendor_org_id))[1], null::uuid,
         max(w.n)::integer, min(w.scanned_at), max(w.scanned_at)
    from rate_w w where w.n >= t.ok_scans_per_minute group by w.scanner_user_id
  union all
  select 'voucher_rescanned', null::uuid, (array_agg(r.vendor_org_id))[1], r.voucher_id,
         count(*)::integer, min(r.scanned_at), max(r.scanned_at)
    from recent r
   where r.result = 'already_redeemed' and r.voucher_id is not null
   group by r.voucher_id
  having count(*) >= t.repeat_scans_per_voucher
  order by 7 desc;
end;
$$;

revoke execute on function redemption_flags_raw() from public, anon, authenticated;

-- --------------------------------------------------------------------------
-- The reader: every flag, with its latest review if that review still covers it
-- --------------------------------------------------------------------------

create or replace function redemption_anomalies()
returns table (
  pattern         text,
  scanner_user_id uuid,
  vendor_org_id   uuid,
  voucher_id      uuid,
  scan_count      integer,
  first_at        timestamptz,
  last_at         timestamptz,
  reviewed_at     timestamptz,
  reviewed_by     uuid
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
begin
  if not is_admin() then
    raise exception 'only an admin may read redemption anomalies';
  end if;

  return query
  select f.pattern, f.scanner_user_id, f.vendor_org_id, f.voucher_id, f.scan_count, f.first_at, f.last_at,
         rv.reviewed_at, rv.reviewed_by
    from redemption_flags_raw() f
    left join lateral (
      select r.reviewed_at, r.reviewed_by
        from redemption_anomaly_reviews r
       where r.pattern = f.pattern
         and r.scanner_user_id is not distinct from f.scanner_user_id
         and r.voucher_id is not distinct from f.voucher_id
         -- A review covers the flag only while no newer scan has fed it.
         and r.flag_last_at >= f.last_at
       order by r.reviewed_at desc
       limit 1
    ) rv on true
   order by f.last_at desc;
end;
$$;

comment on function redemption_anomalies() is
  'Redemption anomaly flags from the last 7 days with review state. Admin only. reviewed_at is null while a flag is open, including after a newer scan reopens it.';

revoke execute on function redemption_anomalies() from public, anon;
grant execute on function redemption_anomalies() to authenticated;

-- --------------------------------------------------------------------------
-- Reviewing
-- --------------------------------------------------------------------------

create or replace function review_redemption_anomaly(
  p_pattern         text,
  p_scanner_user_id uuid,
  p_voucher_id      uuid,
  p_note            text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  flag record;
begin
  if not is_admin() then
    raise exception 'only an admin may review redemption anomalies';
  end if;

  -- Only a flag that exists now, and the review records that flag's own latest scan time.
  select f.* into flag
    from redemption_flags_raw() f
   where f.pattern = p_pattern
     and f.scanner_user_id is not distinct from p_scanner_user_id
     and f.voucher_id is not distinct from p_voucher_id;
  if not found then
    raise exception 'there is no open flag to review for this pattern and subject';
  end if;

  insert into redemption_anomaly_reviews (pattern, scanner_user_id, voucher_id, flag_last_at, reviewed_by, note)
  values (flag.pattern, flag.scanner_user_id, flag.voucher_id, flag.last_at, auth.uid(), nullif(btrim(p_note), ''));
end;
$$;

revoke execute on function review_redemption_anomaly(text, uuid, uuid, text) from public, anon;
grant execute on function review_redemption_anomaly(text, uuid, uuid, text) to authenticated;
commit;

-- ==========================================================================
-- PART 26: 20261103000006_account_removal_gate
-- ==========================================================================
begin;
-- The gate in front of removing a guest's sign-in (the Auth user), after they have erased their data.
--
-- `erase_my_data()` scrubs the profile and keeps bookings. Removing the login itself needs the Auth
-- admin API, which only an Edge Function can call. That function decides nothing: it asks this one.
--
-- Fails closed in five ways, each proven by a test that fails without it:
--   * `privacy.account_removal_enabled` must be exactly `true`. It is seeded `false`. Deleting the
--     Auth user cascades `consent_events`, so the proof of consent goes with the account, and whether
--     that proof must outlive an erased account is a question for counsel (data-inventory.md). Until
--     counsel answers, nothing can be removed. Anything other than boolean true counts as off.
--   * The caller must have erased their data in the last hour: a completed `erasure` row in
--     `privacy_requests`. Removal follows an erasure; it never replaces one.
--   * The guest must hold no bookings. `bookings.user_id` is ON DELETE RESTRICT, so the database
--     would refuse anyway; this answers before the attempt, in words.
--   * Tourist accounts only. Staff are removed by an administrator.
--   * Service role only: revoked from public, anon and authenticated. The subject is the argument,
--     which is safe only because the Edge Function takes it from `auth.getUser(token)`.
--
-- A decision to proceed is recorded in `privacy_requests` as `account_removal` (append-only, no link
-- to the profile), so the removal is accountable after the account is gone.

alter table privacy_requests drop constraint privacy_requests_request_type_check;
alter table privacy_requests add constraint privacy_requests_request_type_check
  check (request_type in ('export', 'erasure', 'account_removal'));

insert into platform_settings (key, value, description)
values (
  'privacy.account_removal_enabled',
  'false'::jsonb,
  'Whether a guest may remove their sign-in after erasing their data. Leave false until counsel has ruled on consent proof (it is deleted with the account). Only boolean true enables it.'
)
on conflict (key) do nothing;

create or replace function begin_account_removal(p_user_id uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  prof profiles%rowtype;
  enabled jsonb;
begin
  select value into enabled from platform_settings where key = 'privacy.account_removal_enabled';
  if enabled is distinct from 'true'::jsonb then
    return 'disabled';
  end if;

  select * into prof from profiles where id = p_user_id;
  if not found or prof.role <> 'tourist' then
    return 'not_tourist';
  end if;

  if not exists (
    select 1 from privacy_requests
     where subject_id = p_user_id and request_type = 'erasure'
       and received_at > now() - interval '1 hour'
  ) then
    return 'not_erased';
  end if;

  if exists (select 1 from bookings where user_id = p_user_id) then
    return 'has_bookings';
  end if;

  insert into privacy_requests (subject_id, request_type, outcome)
  values (p_user_id, 'account_removal', '{}'::jsonb);

  return 'ok';
end;
$$;

comment on function begin_account_removal(uuid) is
  'Decides whether the sign-in of p_user_id may be removed, and records the decision. Returns ok, disabled, not_tourist, not_erased or has_bookings. Service role only.';

revoke execute on function begin_account_removal(uuid) from public, anon, authenticated;
grant execute on function begin_account_removal(uuid) to service_role;
commit;

-- ==========================================================================
-- PART 27: 20261104000001_retention_floor
-- ==========================================================================
begin;
-- Retention floor: a booking or payment younger than 7 years cannot be deleted by accident.
--
-- Decided 2026-11-04: records kept under a legal duty (AML, tax, accounting; GDPR Art 17(3)(b)) are
-- held 7 years from the transaction date. Until now only `bookings.user_id ON DELETE RESTRICT` stood
-- between a bug or a hand-run DELETE and those rows, and `payments` cascades from `bookings`.
--
-- A BEFORE DELETE trigger refuses to remove a row inside the window, for every role including the
-- owner and the service role, and also when the delete arrives as a cascade. The only way through is
-- the future retention job, which must set `cvip.retention_purge` to `on` for its own transaction
-- (`set local`). That job does not exist yet, so today nothing can pass. Past the window, deletes are
-- allowed so the job can purge.
--
-- Not covered: TRUNCATE and DROP TABLE. Both need the table owner; do not grant that to application
-- roles.

create or replace function enforce_retention_floor() returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if coalesce(current_setting('cvip.retention_purge', true), '') = 'on'
     and old.created_at <= now() - interval '7 years' then
    return old;
  end if;
  if old.created_at > now() - interval '7 years' then
    raise exception 'retention floor: % rows are kept 7 years (legal duty)', tg_table_name
      using errcode = 'restrict_violation';
  end if;
  raise exception 'retention floor: % rows past 7 years are removed only by the retention job', tg_table_name
    using errcode = 'restrict_violation';
end
$$;

create trigger bookings_retention_floor before delete on bookings
  for each row execute function enforce_retention_floor();
create trigger payments_retention_floor before delete on payments
  for each row execute function enforce_retention_floor();
commit;
